/* @lc app=leetcode id=2188 lang=kotlin */ class Solution { fun minimumFinishTime(tires: Array<IntArray>, changeTime: Int, numLaps: Int): Int = (1..minOf(numLaps, 20)).map { j -> tires.minOf { (f, r) -> generateSequence(1L) { minOf(it * r, 1_000_000_000_000L) }.take(j).fold(0L) { s, p -> s + f * p } } }.let { best -> (1..numLaps).fold(listOf(0L)) { dp, i -> dp + (1..minOf(i, 20)).minOf { j -> best[j - 1] + dp[i - j] + (if (i - j > 0) changeTime else 0) } }.last().toInt() } }